      "wiki_title": "雙年展",
      "wiki_lang": "zh",
      "wiki_extract": "雙年展（義大利語：biennale）泛指兩年一期的重要藝術展覽。目前最重要的雙年展是意大利威尼斯雙年展。但在其他城市也有不同的藝術雙年展舉行；如巴西聖保羅雙年展，也相當著名。",
