      "wiki_title": "兒童節",
      "wiki_lang": "zh",
      "wiki_extract": "儿童节（英語：Children’s Day）是為了保障儿童的生存权、保健权、受教育权、抚养权等权利、改善儿童生活状况，反对虐待与毒害儿童而设立的节日。\n早在1920年，土耳其民间便开始将4月23日作为国家性的儿童节。1929年，土耳其大国民议会在纪念土耳其獨立戰爭奠定国家基础的重要会议上，正式宣布将这一天设为国定假日。1981年，该节日被正式命名为“国家主权及儿童日”。\n1949年，苏联莫斯科举行的国际民主妇女联合会大会为悼念1942年利迪策惨案，倡议将6月1日设为国际儿童节，现由40多个国家采用。\n1954年12月14日，聯合國教育科學文化組織定訂11月20日爲世界儿童日。\n儿童节設立目的最先是為促進成人與兒童之間的相互交流和了解，其次則是要人們採取行動以受益促進世界兒童的福利，並以促進確立《聯合國憲章》保障兒童福利為目標。1989年11月20日聯合國通過《兒童權利宣言》。",
      "wiki_url": "https://zh.wikipedia.org/wiki/%E5%85%92%E7%AB%A5%E7%AF%80",
