      "wiki_title": "Mario",
      "wiki_lang": "en",
      "wiki_extract": "Mario (  MAR(R)-ee-oh; Japanese: マリオ) is a character created by Japanese video game designer Shigeru Miyamoto. He is the star of the Mario franchise, a recurring character in the Donkey Kong franchise, and the mascot of their owner, the Japanese company Nintendo. Mario is an Italian-American plumber who lives in the Mushroom Kingdom with his younger twin brother, Luigi. Their adventures generally involve rescuing Princess Peach from the villain Bowser while using power-ups that give them different abilities. Mario is distinguished by his large nose and mustache, overalls, red cap, and high-pitched, exaggerated Italian accent. Prior to being named Mario, the character was referred to as Ossan, Mr. Video, and Jumpman.\nMario debuted as the player character of Donkey Kong, a 1981 platform game. Miyamoto created Mario because Nintendo was unable to license Popeye as the protagonist. The graphical limitations of arcade hardware influenced Mario's design, such as his nose, mustache, and overalls, and he was named after Nintendo of America's landlord, Mario Segale. Mario then starred in Mario Bros. (1983). Its 1985 Nintendo Entertainment System sequel, Super Mario Bros., began the successful Super Mario platformer series. Charles Martinet voiced Mario from 1991 to 2023, when he was succeeded by Kevin Afghani.\nMario has appeared in hundreds of video games. These include puzzle games such as Dr. Mario, role-playing games such as Paper Mario and Mario & Luigi, and sports games such as Mario Kart and Mario Tennis. He lacks a set personality and consistent profession, allowing him to take on many different roles across the Mario franchise. Mario is often accompanied by a large cast of supporting characters, including friends like Princess Daisy, Toad, and Yoshi and rivals like Bowser Jr., Donkey Kong, and Wario. Mario appears in other Nintendo properties, such as the Super Smash Bros. series of crossover fighting games.\nMario is an established pop culture icon and one of the most famous characters in history. His likeness has been featured in merchandise, and people and places have been nicknamed after him. He inspired many video game characters, including Sega's Sonic the Hedgehog, and unofficial media. The Mario franchise is the best-selling video game franchise of all time. Mario has been adapted in various media; he was portrayed in live-action by Lou Albano in The Super Mario Bros. Super Show! and by Bob Hoskins in the 1993 film Super Mario Bros.. Chris Pratt voiced him in the animated films The Super Mario Bros. Movie (2023) and The Super Mario Galaxy Movie (2026).",
