      "wiki_extract": "日，一般指地球日，是时间单位。\n\n时长单位，也称天，大約是地球相對太陽自轉一周之时长，即一晝夜循環。自1967年后，科学上「日」已经由國際度量衡局（BIPM）以原子能階躍遷规定为86400秒。一日 = 24 小时 = 86400秒。\n时刻单位，也称号，日期的简称，如：今日是2026年11月13日，这里的「日」是指11月第13日。\n「日」有时指每週的星期日。口语中，「日」或者「天」有时也可能特指白晝，即不包括夜晚之半日時間。",
