      "wiki_title": "双十一",
      "wiki_lang": "zh",
      "wiki_extract": "双十一，又称双十一购物节，是以每年11月11日为核心日期的大型购物促销活动，主要由中国电子商务平台及零售企业参与。\n2009年，阿里巴巴旗下淘宝商城首次在11月11日举行集中促销，此后活动逐渐扩展至其他电商平台、实体零售商及跨境电商。经过十余年发展，“双十一”现已超越“网络星期一”，成为全球最大规模的网络购物节日，其促销周期亦已明显拉长。",
