      "wiki_lang": "zh",
      "wiki_extract": "九皇大帝又稱九皇爺、九王爺、九皇，是道教和民間傳說的星神，起源有古代帝王、北斗神等多種，並盛行於馬來西亞、新加坡、泰國、台灣等地方。",
