      "wiki_title": "骄傲月",
      "wiki_lang": "zh",
      "wiki_extract": "LGBT骄傲月，简称骄傲月，是专门用于庆祝和纪念女同性恋、男同性恋、双性恋和跨性别者（合称LGBT）的骄傲的一个月份，通常在六月。骄傲月始于1969年石牆暴動（一系列同性恋解放运动）之后。",
